def page(title,content):return '<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(title)+'</title><style>'+style+'</style><main>'+content+'</main></html>'
def render(src,dest):
    text=src.read_text(encoding='utf-8');body=markdown.markdown(text,extensions=['tables','fenced_code'])
    body='<p><a href="../ABRA_PRIMEIRO.html">← Voltar ao início do pacote</a></p>'+body
    dest.write_text(page(src.stem,body),encoding='utf-8')
